export const DASHBOARD_BREADCRUMB = {
  label: "DASHBOARD",
  path: "/dashboard",
};

const withDefinedLabel = (item) => item && item.label;
const withoutBreadcrumbTrail = (state) => {
  if (!state || typeof state !== "object") {
    return state;
  }

  const { breadcrumbTrail, ...rest } = state;
  return rest;
};

export const buildBreadcrumbTrail = (...items) =>
  items.filter(withDefinedLabel);

export const createRequestDetailsCrumb = ({
  requestId,
  requestData,
  requestLabel = "REQUEST_DETAILS",
} = {}) => ({
  label: requestLabel,
  path: requestId ? `/request/${requestId}` : null,
  state: withoutBreadcrumbTrail(requestData),
});

export const createRequestDetailsTrail = (options = {}) =>
  buildBreadcrumbTrail(
    DASHBOARD_BREADCRUMB,
    createRequestDetailsCrumb(options),
  );

export const createOrganizationsPageState = ({
  requestId,
  requestData,
  requestLabel = "REQUEST_DETAILS",
  organizationsLabel = "ORGANIZATIONS",
} = {}) => {
  const requestCrumb = createRequestDetailsCrumb({
    requestId,
    requestData,
    requestLabel,
  });

  return {
    ...withoutBreadcrumbTrail(requestData),
    breadcrumbTrail: buildBreadcrumbTrail(DASHBOARD_BREADCRUMB, requestCrumb, {
      label: organizationsLabel,
      path: "/voluntary-organizations",
    }),
  };
};

export const createOrganizationDetailsTrail = ({
  organizationName,
  requestId,
  requestData,
  requestLabel = "REQUEST_DETAILS",
  organizationsLabel = "ORGANIZATIONS",
} = {}) => {
  const organizationsPageState = createOrganizationsPageState({
    requestId,
    requestData,
    requestLabel,
    organizationsLabel,
  });

  return buildBreadcrumbTrail(
    ...organizationsPageState.breadcrumbTrail.slice(0, 2),
    {
      ...organizationsPageState.breadcrumbTrail[2],
      state: organizationsPageState,
    },
    {
      label: organizationName || "ORGANIZATION_DETAILS",
    },
  );
};

import React from "react";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import Breadcrumbs from "./BreadCrumbs";

// The repo-wide __mocks__/react-router-dom.jsx replaces the router; this
// component needs the real useLocation/Link/MemoryRouter to be tested.
jest.mock("react-router-dom", () => jest.requireActual("react-router-dom"));
import {
  DASHBOARD_BREADCRUMB,
  buildBreadcrumbTrail,
  createRequestDetailsCrumb,
  createRequestDetailsTrail,
  createOrganizationsPageState,
  createOrganizationDetailsTrail,
} from "./breadcrumbUtils";

const renderAt = (entry) =>
  render(
    <MemoryRouter initialEntries={[entry]}>
      <Breadcrumbs />
    </MemoryRouter>,
  );

describe("Breadcrumbs", () => {
  it("renders nothing on hidden routes", () => {
    const hiddenRoutes = [
      "/",
      "/home",
      "/login",
      "/signup",
      "/forgot-password",
      "/verify-account",
      "/verify-otp",
    ];
    hiddenRoutes.forEach((route) => {
      const { container, unmount } = renderAt(route);
      expect(container.querySelector(".breadcrumb-nav")).toBeNull();
      unmount();
    });
  });

  it("renders a translated Home crumb", () => {
    renderAt("/dashboard");
    expect(screen.getByText("mockTranslate(HOME)")).toBeTruthy();
  });

  it("renders the dashboard as a single active crumb", () => {
    renderAt("/dashboard");
    expect(screen.getByText("mockTranslate(DASHBOARD)")).toBeTruthy();
  });

  it.each([
    ["/request", "CREATE_HELP_REQUEST"],
    ["/request/123", "REQUEST_DETAILS"],
    ["/promote-to-volunteer", "PROMOTE_TO_VOLUNTEER"],
    ["/emergency-contact", "EMERGENCY_CONTACT"],
    ["/voluntary-organizations", "ORGANIZATIONS"],
    ["/profile", "PROFILE"],
  ])(
    "renders %s under the Dashboard section with key %s",
    (route, expectedKey) => {
      renderAt(route);
      expect(screen.getByText("mockTranslate(DASHBOARD)")).toBeTruthy();
      expect(screen.getByText(`mockTranslate(${expectedKey})`)).toBeTruthy();
    },
  );

  it.each([
    ["/our-team", "ABOUT", "OUR_TEAM"],
    ["/our-mission", "ABOUT", "OUR_MISSION"],
    ["/news-our-stories", "ABOUT", "IN_THE_NEWS"],
    ["/how-we-operate", "VOLUNTEER_SERVICES", "HOW_WE_OPERATE"],
    ["/collaborators", "VOLUNTEER_SERVICES", "OUR_COLLABORATORS"],
  ])(
    "renders %s under parent key %s with page key %s",
    (route, parent, page) => {
      renderAt(route);
      expect(screen.getByText(`mockTranslate(${parent})`)).toBeTruthy();
      expect(screen.getByText(`mockTranslate(${page})`)).toBeTruthy();
    },
  );

  it.each([
    ["/contact", "CONTACT"],
    ["/notifications", "NOTIFICATIONS"],
    ["/donate", "DONATE"],
  ])(
    "renders standalone page %s as a single crumb with key %s",
    (route, key) => {
      renderAt(route);
      expect(screen.getByText(`mockTranslate(${key})`)).toBeTruthy();
    },
  );

  it.each([
    ["/terms-and-conditions", "TERMS_AND_CONDITIONS"],
    ["/privacy-policy", "PRIVACY_POLICY"],
    ["/sitemap", "SITEMAP"],
    ["/thanks", "THANKS"],
    ["/benevity", "BENEVITY"],
  ])("renders section page %s with key %s", (route, key) => {
    renderAt(route);
    expect(screen.getByText(`mockTranslate(${key})`)).toBeTruthy();
  });

  it("renders the organization name from navigation state on organization routes", () => {
    render(
      <MemoryRouter
        initialEntries={[
          {
            pathname: "/organization/42",
            state: { organizationData: { Name: "Helping Hands" } },
          },
        ]}
      >
        <Breadcrumbs />
      </MemoryRouter>,
    );
    expect(screen.getByText("mockTranslate(Helping Hands)")).toBeTruthy();
  });

  it("falls back to the ORGANIZATION_DETAILS key when no organization name is passed", () => {
    renderAt("/organization/42");
    expect(
      screen.getByText("mockTranslate(ORGANIZATION_DETAILS)"),
    ).toBeTruthy();
  });

  it("prettifies unknown route segments as a fallback label", () => {
    renderAt("/some-unknown-page");
    expect(screen.getByText("mockTranslate(Some Unknown Page)")).toBeTruthy();
  });

  it("renders a breadcrumb trail passed through navigation state with links", () => {
    const trail = createRequestDetailsTrail({ requestId: "99" });
    render(
      <MemoryRouter
        initialEntries={[
          { pathname: "/request/99", state: { breadcrumbTrail: trail } },
        ]}
      >
        <Breadcrumbs />
      </MemoryRouter>,
    );
    const dashboardLink = screen.getByText("mockTranslate(DASHBOARD)");
    expect(dashboardLink.closest("a").getAttribute("href")).toBe("/dashboard");
    expect(screen.getByText("mockTranslate(REQUEST_DETAILS)")).toBeTruthy();
  });
});

describe("breadcrumbUtils", () => {
  it("uses the DASHBOARD translation key for the dashboard crumb", () => {
    expect(DASHBOARD_BREADCRUMB).toEqual({
      label: "DASHBOARD",
      path: "/dashboard",
    });
  });

  it("filters out items without labels when building a trail", () => {
    const trail = buildBreadcrumbTrail(
      DASHBOARD_BREADCRUMB,
      null,
      { path: "/no-label" },
      { label: "OK" },
    );
    expect(trail).toEqual([DASHBOARD_BREADCRUMB, { label: "OK" }]);
  });

  it("creates a request details crumb with the REQUEST_DETAILS key by default", () => {
    const crumb = createRequestDetailsCrumb({
      requestId: "7",
      requestData: { breadcrumbTrail: ["stale"], subject: "Food" },
    });
    expect(crumb.label).toBe("REQUEST_DETAILS");
    expect(crumb.path).toBe("/request/7");
    expect(crumb.state).toEqual({ subject: "Food" });
  });

  it("creates the organizations page state with translation keys", () => {
    const state = createOrganizationsPageState({ requestId: "7" });
    expect(state.breadcrumbTrail.map((item) => item.label)).toEqual([
      "DASHBOARD",
      "REQUEST_DETAILS",
      "ORGANIZATIONS",
    ]);
  });

  it("uses the organization name when provided and the key as fallback", () => {
    const named = createOrganizationDetailsTrail({
      organizationName: "Helping Hands",
      requestId: "7",
    });
    expect(named[named.length - 1].label).toBe("Helping Hands");

    const fallback = createOrganizationDetailsTrail({ requestId: "7" });
    expect(fallback[fallback.length - 1].label).toBe("ORGANIZATION_DETAILS");
  });
});

src/common/components/DataTable/Table.js:
import { useEffect, useMemo } from "react";
import { Link } from "react-router-dom";
import PropTypes from "prop-types";
import { useTranslation } from "react-i18next";
import Pagination from "../Pagination/Pagination";

const Table = ({
  headers,
  rows,
  currentPage,
  setCurrentPage,
  totalPages,
  totalRows,
  itemsPerPage,
  sortConfig,
  requestSort,
  onRowsPerPageChange,
  getLinkPath,
  getLinkState = undefined,
  serverPaginated = false,
}) => {
  const { t, i18n } = useTranslation(["common", "categories"]);

  const paginatedRequests = useMemo(() => {
    if (serverPaginated) {
      return rows;
    }

    return rows.slice(
      (currentPage - 1) * itemsPerPage,
      currentPage * itemsPerPage,
    );
  }, [rows, currentPage, itemsPerPage, serverPaginated]);

  //useEffect(() => {
  //setCurrentPage(1);
  //}, [totalRows, itemsPerPage, setCurrentPage]);

  const getSortIndicator = (key) => {
    if (sortConfig.key === key) {
      return sortConfig.direction === "ascending" ? "↑" : "↓";
    }
    return "";
  };

  const formatDateTime = (value, header) => {
    if (header === "creationDate" || header === "updatedDate") {
      if (!value) return "";

      try {
        const date = new Date(value);
        if (Number.isNaN(date.getTime())) return value;

        const datePart = date.toLocaleDateString("en-US", {
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
        });
        const timePart = date.toLocaleTimeString("en-US", {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: true,
        });
        return `${datePart} ${timePart}`;
      } catch (error) {
        console.error("Error formatting date:", error);
        return value;
      }
    }
    return value;
  };

  const dataKeyMap = {
    requestId: "requestId",
    beneficiaryId: "userId",
    category: "requestCategory",
  };
  const resolveKey = (header) => dataKeyMap[header] || header;

  const headerLabelMap = {
    status: t("STATUS"),
    subject: t("SUBJECT"),
    type: t("TYPE"),
    category: t("Category"),
    priority: t("PRIORITY"),
    requestId: t("Request ID"),
    updatedDate: t("Last Updated"),
    creationDate: t("Created"),
    calamity: t("Calamity"),
    beneficiaryCreatorDisplayId: t("Beneficiary ID / Creator ID"),
    leadVolunteerDisplayId: t("Lead Volunteer ID"),
  };

  const getCategoryLabel = (code) => {
    if (!code) return code;
    const bundle =
      i18n.getResourceBundle(i18n.language, "categories") ||
      i18n.getResourceBundle("en", "categories");
    if (!bundle?.REQUEST_CATEGORIES) return code;
    const search = (obj, target) => {
      for (const key in obj) {
        if (key === target && obj[key].LABEL) return obj[key].LABEL;
        if (obj[key].SUBCATEGORIES) {
          const found = search(obj[key].SUBCATEGORIES, target);
          if (found) return found;
        }
      }
      return null;
    };
    return search(bundle.REQUEST_CATEGORIES, code) || code;
  };

  const splitRequestIdLines = (requestId) => {
    if (typeof requestId !== "string") return [requestId];
    const parts = requestId.split("-");
    if (parts.length < 5) return [requestId];

    return [
      `${parts[0]}-${parts[1]}-`,
      `${parts[2]}-${parts[3]}-`,
      parts.slice(4).join("-"),
    ];
  };

  const getCellValue = (row, header) => {
    if (header === "requestId") return row[resolveKey(header)];
    if (header === "category") return getCategoryLabel(row[resolveKey(header)]);
    const value = formatDateTime(row[resolveKey(header)], header);
    if (
      ["beneficiaryCreatorDisplayId", "leadVolunteerDisplayId"].includes(
        header,
      ) &&
      (value === null || value === undefined || value === "")
    ) {
      return "—";
    }
    return value;
  };

  const renderRequestId = (requestId) =>
    splitRequestIdLines(requestId).map((line, index) => (
      <span
        key={`${requestId}-${index}`}
        className="block whitespace-nowrap leading-tight"
      >
        {line}
      </span>
    ));

  const getCellClassName = (header) => {
    if (header === "requestId") {
      return "px-3 py-2 text-sm leading-tight align-top";
    }
    if (
      ["beneficiaryCreatorDisplayId", "leadVolunteerDisplayId"].includes(header)
    ) {
      return "px-6 py-2 whitespace-nowrap text-sm";
    }
    return "px-6 py-2";
  };

  const shouldLinkCell = (header) => header === "requestId" || header === "id";

  return (
    <div className="relative h-full" data-testid="container">
      <div className="overflow-auto h-4/5">
        <table
          className="min-w-full divide-y divide-gray-200"
          data-testid="table"
        >
          <thead data-testid="table-header">
            <tr>
              {headers.map((key) => (
                <th
                  key={key}
                  className="px-6 py-2 text-left text-xs font-medium text-gray-600 uppercase tracking-wider"
                  data-testid="map-header-one"
                >
                  <button
                    type="button"
                    onClick={() => requestSort(resolveKey(key))}
                  >
                    {headerLabelMap[key] ||
                      key.charAt(0).toUpperCase() +
                        key
                          .slice(1)
                          .replace(/([A-Z])/g, " $1")
                          .trim()}
                    {getSortIndicator(resolveKey(key))}
                  </button>
                </th>
              ))}
            </tr>
          </thead>

          <tbody
            className="bg-white divide-y divide-gray-200"
            data-testid="table-body"
          >
            {paginatedRequests.length === 0 ? (
              <tr>
                <td
                  colSpan={headers.length}
                  className="px-6 py-8 text-center text-gray-500"
                >
                  <div className="flex flex-col items-center justify-center">
                    <p className="text-lg font-semibold mb-2">
                      No requests found
                    </p>
                    <p className="text-sm">
                      {rows.length === 0
                        ? "There are no requests to display."
                        : "Try adjusting your filters to see more results."}
                    </p>
                  </div>
                </td>
              </tr>
            ) : (
              paginatedRequests.map((row, rowIndex) => (
                <tr key={rowIndex}>
                  {headers.map((header, colIndex) => {
                    const value = getCellValue(row, header);

                    const path = getLinkPath ? getLinkPath(row, header) : null;
                    const cellContent =
                      header === "requestId" ? renderRequestId(value) : value;

                    return (
                      <td
                        key={colIndex}
                        className={getCellClassName(header)}
                        data-testid="map-data-one"
                      >
                        {path ? (
                          <Link
                            to={path}
                            className="text-indigo-600 hover:text-indigo-900"
                            state={getLinkState ? getLinkState(row) : undefined}
                          >
                            {cellContent}
                          </Link>
                        ) : (
                          cellContent
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <div className="h-1/5">
        {rows.length > 0 && (
          <Pagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={setCurrentPage}
            rowsPerPage={itemsPerPage}
            totalRows={totalRows}
            onRowsPerPageChange={onRowsPerPageChange}
          />
        )}
      </div>
    </div>
  );
};

Table.propTypes = {
  headers: PropTypes.arrayOf(PropTypes.string).isRequired,
  rows: PropTypes.array.isRequired,
  currentPage: PropTypes.number.isRequired,
  setCurrentPage: PropTypes.func.isRequired,
  totalPages: PropTypes.number.isRequired,
  totalRows: PropTypes.number.isRequired,
  itemsPerPage: PropTypes.number.isRequired,
  sortConfig: PropTypes.shape({
    key: PropTypes.string,
    direction: PropTypes.oneOf(["ascending", "descending"]),
  }).isRequired,
  requestSort: PropTypes.func.isRequired,
  onRowsPerPageChange: PropTypes.func.isRequired,
  getLinkPath: PropTypes.func.isRequired,
  getLinkState: PropTypes.func,
  serverPaginated: PropTypes.bool,
};

export default Table;

