import { useEffect, useState } from "react";

const ScrollToTop = () => {
  const [show, setShow] = useState(true);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setShow(!entry.isIntersecting),
      { threshold: 0.1 },
    );
    const header = document.getElementById("header");
    if (header) observer.observe(header);
    return () => observer.disconnect();
  }, []);

  if (!show) return null;

  return (
    <button
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      className="fixed bottom-4 right-4 w-8 h-8 sm:w-12 sm:h-12 bg-gray-200 text-black hover:bg-gray-300 rounded-full z-50 flex items-center justify-center text-xl sm:text-2xl font-extrabold"
    >
      ↑
    </button>
  );
};

export default ScrollToTop;

//Mock IntersectionObserver for Jest environment which is supported by React
beforeAll(() => {
  global.IntersectionObserver = class {
    constructor(callback) {
      this.callback = callback;
    }
    observe() {
      this.callback([{ isIntersecting: false }]);
    }
    unobserve() {}
    disconnect() {}
  };
});

import "@testing-library/jest-dom";
import { render, screen, fireEvent } from "@testing-library/react";
import ScrollToTop from "./ScrollToTop";

describe("ScrollToTop", () => {
  beforeEach(() => {
    //dummy header element
    const header = document.createElement("div");
    header.setAttribute("id", "header");
    document.body.appendChild(header);
  });

  afterEach(() => {
    const header = document.getElementById("header");
    if (header) header.remove();
  });

  //test case 1
  it("renders the scroll button", () => {
    render(<ScrollToTop />);
    const button = screen.getByRole("button");
    expect(button).toBeInTheDocument();
  });

  //test case 2
  it("scrolls to top on click", () => {
    const scrollSpy = jest.spyOn(window, "scrollTo");
    render(<ScrollToTop />);
    const button = screen.getByRole("button");
    fireEvent.click(button);
    expect(scrollSpy).toHaveBeenCalledWith({
      top: 0,
      behavior: "smooth",
    });
  });
});

