    } else {
      setTypeFilter((prev) => {
        const updated = {
          ...prev,
          [value]: !prev[value],
        };

        const nonAllValues = typeOptions
          .filter((t) => t.value !== "All")
          .map((t) => t.value);

        const allSelected = nonAllValues.every((v) => updated[v]);

        updated["All"] = allSelected;

        return updated;
      });
    }
