      <div className="flex space-x-4 mb-6">
        <label>
          <input
            type="radio"
            value="jobSeeker"
            checked={userType === "jobSeeker"}
            onChange={() => setUserType("jobSeeker")}
          />
          Job Seeker
        </label>
        <label>
          <input
            type="radio"
            value="hiringManager"
            checked={userType === "hiringManager"}
            onChange={() => setUserType("hiringManager")}
          />
          Hiring Manager
