      </div>

      {userType === "jobSeeker" && (
        <>
          {/* Job Seeker Fields */}
          <div className="mb-6">
            <h3 className="font-semibold">Upload Resume</h3>
            <input
              type="file"
              onChange={handleFileChange}
              style={{ color: "blue" }}
