const HelpRequestForm = ({ isEdit = false, onClose, editRequestData }) => {
  const { t, i18n } = useTranslation(["common", "categories"]);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { categories, categoriesFetched } = useSelector(
    (state) => state.request,
  );
  const groups = useSelector((state) => state.auth.user?.groups);
  const userDbId = useSelector((state) => state.auth.user?.userDbId);
  const user = useSelector((state) => state.auth.user);
  const [location, setLocation] = useState("");
  const [locationCoordinates, setLocationCoordinates] = useState(null);
  const { inputRef, suggestions, handleSearchChange, handleSelectSuggestion } =
    usePlacesSearchBox(setLocation, (coords) => {
      setLocationCoordinates(coords);
      setFormData((prev) => ({ ...prev, locationCoordinates: coords }));
    });

  // NEW (SAAYAM-1622): separate location state/hook for the "Other" requester's
  // address. Intentionally kept OUT of formData/submissionData for now since
  // there is no API/DB field mapped for it yet. Once the API adds support for
  // storing this in the geography column, wire otherPersonLocation /
  // otherPersonLocationCoordinates into submissionData in handleSubmit below.
  const [otherPersonLocation, setOtherPersonLocation] = useState("");
  const [otherPersonLocationCoordinates, setOtherPersonLocationCoordinates] =
    useState(null);
  const {
    inputRef: otherLocationInputRef,
    suggestions: otherLocationSuggestions,
    handleSearchChange: handleOtherLocationSearchChange,
    handleSelectSuggestion: handleOtherLocationSelectSuggestion,
  } = usePlacesSearchBox(setOtherPersonLocation, (coords) => {
    setOtherPersonLocationCoordinates(coords);
  });

  const [languages, setLanguages] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState("General");
  const [filteredCategories, setFilteredCategories] = useState([]);
  const [searchInput, setSearchInput] = useState("");
  const [requestType, setRequestType] = useState("");
  const [hoveredCategory, setHoveredCategory] = useState(null);
  const [hoveredSubcategory, setHoveredSubcategory] = useState(null);
  const [showDropdown, setShowDropdown] = useState(false);
  const [suggestedCategories, setSuggestedCategories] = useState([]);
  const [selectedCategoryId, setSelectedCategoryId] = useState(null);
  const [categoryConfirmed, setCategoryConfirmed] = useState(false);
  const [enums, setEnums] = useState(null);
  // Popup modal for subcategory - State for Elderly Support inline form
  const [showElderlySupportForm, setShowElderlySupportForm] = useState(false);
  const [selectedElderlySubcategory, setSelectedElderlySubcategory] =
    useState(null);
  const [elderlySupportData, setElderlySupportData] = useState({});
  // Popup modal for subcategory - Track which subcategory is currently saved
  const [savedSubcategoryId, setSavedSubcategoryId] = useState(null);
  // stores multiple file errors
  const [fileErrorMessages, setFileErrorMessages] = useState([]);
  // Dynamic additional fields state
  const [additionalFieldValues, setAdditionalFieldValues] = useState({});
  const hasUserEditedAdditionalFieldsRef = useRef(false);

  // useEffect(() => {
  //   const fetchEnumsData = async () => {
  //     try {
  //       const data = await getEnums();
  //       // console.log("Enums API response:", data);

  //       setEnums(data);
  //     } catch (error) {
  //       console.error("Failed to fetch enums:", error);
  //     }
  //   };

  //   fetchEnumsData();
  // }, []);

  useEffect(() => {
    const storedEnums = localStorage.getItem("enums");
    if (storedEnums) {
      setEnums(JSON.parse(storedEnums));
    } else {
      console.warn("Enums not found in localStorage, please re-login.");
    }
  }, []);

  const invertEnum = (obj) =>
    Object.entries(obj).reduce((acc, [key, value]) => {
      acc[value] = Number(key);
      return acc;
    }, {});

  const enumMaps = enums
    ? {
        requestFor: invertEnum(enums.requestFor),
        requestPriority: invertEnum(enums.requestPriority),
        requestType: invertEnum(enums.requestType),
      }
    : null;

  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "info", // 'success', 'error', 'warning' also valid
  });

  const { data, error, isLoading } = useGetAllRequestQuery();
  const [addRequest] = useAddRequestMutation();
  const { id } = useParams();

  const inputref = useRef(null);
  const dropdownRef = useRef(null);
  const fileInputRef = useRef(null);
  // Tracks whether the user has manually edited the subject field.
  // When true, auto-generation from description is suppressed.
  const hasUserEditedSubjectRef = useRef(false);

  const [formData, setFormData] = useState({
    is_self: "yes",
    requester_first_name: "",
    requester_last_name: "",
    email: "",
    phone: "",
    age: "",
    gender: "Select",
    lead_volunteer: "Ethan Marshall",
    is_calamity: false,
    preferred_language: (() => {
      const saved = JSON.parse(localStorage.getItem("userPreferences") || "{}");
      return saved.languagePreference1 || "";
    })(),
    category: "General",
    request_type: "REMOTE",
    location: "",
    subject: "",
    description: "",
    priority: "MEDIUM",
    detected_language: "", // Language detected from audio transcription (e.g., "hi", "en", "es")
  });

  // One-time prefill: when requesting on behalf of someone else (For Self
  // = Other) with an In Person request, default the In Person location to
  // the Other person's location - it's logically the same place (e.g. a
  // roadside location, a friend's address). Fires once; both fields are
  // freely/independently editable afterward.
  const hasPrefilledInPersonFromOtherRef = useRef(false);
  useEffect(() => {
    if (
      formData.request_for === "OTHER" &&
      formData.request_type === "IN_PERSON" &&
      otherPersonLocation &&
      !hasPrefilledInPersonFromOtherRef.current
    ) {
      hasPrefilledInPersonFromOtherRef.current = true;
      setLocation(otherPersonLocation);
      setFormData((prev) => ({ ...prev, location: otherPersonLocation }));
      if (otherPersonLocationCoordinates) {
        setLocationCoordinates(otherPersonLocationCoordinates);
        setFormData((prev) => ({
          ...prev,
          locationCoordinates: otherPersonLocationCoordinates,
        }));
      }
    }
  }, [
    formData.request_for,
    formData.request_type,
    otherPersonLocation,
    otherPersonLocationCoordinates,
  ]);

  // If user changes category to a non-elderly option, ensure any open ElderlySupport panel is closed
  useEffect(() => {
    // Resolve whether current formData.category corresponds to an Elderly subcategory
    const isElderlySubcategory = (() => {
      if (!formData.category || !categories) return false;
      // check if category matches a subcategory id or name under ELDERLY_SUPPORT
      for (const cat of categories) {
        if (!cat.subCategories || cat.subCategories.length === 0) continue;
        if (cat.catName === "ELDERLY_SUPPORT") {
          const match = cat.subCategories.find(
            (s) =>
              s.catId === formData.category || s.catName === formData.category,
          );
          if (match) return true;
        }
      }
      return false;
    })();

    if (!isElderlySubcategory) {
      // close any inline elderly support form if it's open and the selected category is not elderly
      if (showElderlySupportForm || selectedElderlySubcategory) {
        setShowElderlySupportForm(false);
        setSelectedElderlySubcategory(null);
      }
    }
  }, [formData.category, categories]);

  // FILE UPLOAD STATE
  // attachedFiles: array of File objects selected by user (not yet uploaded)
  const [attachedFiles, setAttachedFiles] = useState([]);
  // uploadProgress: { fileId: progressNumber (0-100) }
  const [uploadProgress, setUploadProgress] = useState({});
  // uploadedFilesInfo: [{ name, size, fileUrl }]
  const [uploadedFilesInfo, setUploadedFilesInfo] = useState([]);
  const [showFilesDialog, setShowFilesDialog] = useState(false);
  const [isUploadingFiles, setIsUploadingFiles] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  // Audio recording state
  const [audioUploadResult, setAudioUploadResult] = useState(null);
  const [audioBlob, setAudioBlob] = useState(null); // Store audio blob for submission

  const firstString = (...values) =>
    values.find((value) => typeof value === "string" && value.trim() !== "");

  const resolveCatNameToId = (catNameOrId) => {
    if (!catNameOrId || !categories) return catNameOrId;
    const isNumericId = /^\d+(\.\d+)*$/.test(catNameOrId);
    if (isNumericId) return catNameOrId;
    for (const cat of categories) {
      if (cat.catName === catNameOrId) return cat.catId;
      for (const sub of cat.subCategories || []) {
        if (sub.catName === catNameOrId) return sub.catId;
        for (const subsub of sub.subCategories || []) {
          if (subsub.catName === catNameOrId) return subsub.catId;
        }
      }
    }
    return catNameOrId;
