  const validateFile = (file) => {
    if (!ALLOWED_MIME_TYPES.includes(file.type)) {
      return {
        ok: false,
        code: 2034,
        message: `${file.name} is not an allowed format. Please select PNG, JPG, JPEG, or PDF.`,
      };
