  const handleFileSelection = (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    // reset previous file errors
    setFileErrorMessages([]);

    // enforce total count
    if (attachedFiles.length + files.length > MAX_FILES) {
      setFileErrorMessages([
        t(
          "SAAYAM-2036: You can only attach up to {{max}} files (including already attached files). Please try again.",
          { max: MAX_FILES },
        ),
      ]);
      return;
    }

    const validated = [];
    const errors = [];

    for (const file of files) {
      //prevent duplicate attachments
      const isDuplicate = attachedFiles.some(
        (f) =>
          f.name === file.name &&
          f.size === file.size &&
          f.lastModified === file.lastModified,
      );
      //duplicate check
      if (isDuplicate) {
        errors.push(
          t(
            "SAAYAM-2037: The file '{{fileName}}' is already attached. Please choose a different file.",
            { fileName: file.name },
          ),
        );
        continue;
      }

      const v = validateFile(file);
      if (!v.ok) {
        errors.push(t(`SAAYAM-${v.code}: ${v.message}`));
        continue; // skip invalid file
      }
      validated.push(file);
    }

    // show all errors
    if (errors.length > 0) {
      setFileErrorMessages(errors);
    }

    if (validated.length === 0) return;
    setAttachedFiles((prev) => [...prev, ...validated]);
    // reset input so same file can be reselected if removed later
    e.target.value = "";
  };

  const removeAttachedFile = (index) => {
    setAttachedFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const removeUploadedFile = (index) => {
    setUploadedFilesInfo((prev) => prev.filter((_, i) => i !== index));
  };

  // Format long file names (keep first 45 chars + extension)
  const formatFileName = (fileName) => {
    const maxLen = 43;
    const dotIndex = fileName.lastIndexOf(".");
    const ext = dotIndex !== -1 ? fileName.slice(dotIndex) : "";
    const base = dotIndex !== -1 ? fileName.slice(0, dotIndex) : fileName;

    if (base.length > maxLen) {
      return base.slice(0, maxLen) + "..." + ext;
    }

    return fileName;
  };

  // Format file size into KB/MB
  const formatFileSize = (bytes) => {
    if (bytes >= 1024 * 1024) {
      return (bytes / (1024 * 1024)).toFixed(2) + " MB";
    }
    return (bytes / 1024).toFixed(2) + " KB";
  };

  // Upload single file to backend and return the file URL
  const uploadSingleFile = async (file, index) => {
    return new Promise(async (resolve, reject) => {
      try {
        // Upload using axios interceptor (requestServices.js)
        const res = await uploadRequestFile(file);

        // assume response contains { fileUrl: "..." } or { url: "..." } - adapt if different
        const fileUrl = res?.fileUrl || res?.url || res?.fileUrl?.[0] || null;

        if (!fileUrl) {
          // Backend didn't return expected URL
          console.warn("Upload response:", res);
          reject(new Error("Upload failed - no file URL returned"));
          return;
        }

        // mark progress as 100%
        setUploadProgress((prev) => ({ ...prev, [file.name || index]: 100 }));

        resolve(fileUrl);
      } catch (err) {
        console.error("Upload error for file:", file.name, err);
        setUploadProgress((prev) => ({ ...prev, [file.name || index]: 0 }));
        reject(err);
      }
    });
  };

  // Upload all attached files (called during submit)
  const uploadAllAttachedFiles = async () => {
    if (!attachedFiles || attachedFiles.length === 0) return [];

    setIsUploadingFiles(true);
    setUploadProgress({});
    const uploadedUrls = [];
    const uploadedInfo = [];

    for (let i = 0; i < attachedFiles.length; i++) {
      const file = attachedFiles[i];
      try {
        const url = await uploadSingleFile(file, i);
        uploadedUrls.push(url);
        uploadedInfo.push({
          name: file.name,
          size: file.size,
          fileUrl: url,
        });
      } catch (err) {
        // If one file fails, show error but continue uploading others (you can change to abort instead)
        setSnackbar({
          open: true,
          message: `Failed to upload ${file.name}. Please try again.`,
          severity: "error",
        });
      }
    }

    setIsUploadingFiles(false);
    // append to uploadedFilesInfo (persist uploaded results)
    setUploadedFilesInfo((prev) => [...prev, ...uploadedInfo]);
    // clear attachedFiles since they are uploaded now (but only if you want to clear them)
    // We will clear them so UI shows uploadedFilesInfo instead
    setAttachedFiles([]);
    return uploadedUrls;
  };

  // ---------- SUBMIT HANDLER (modified to upload files before creating request) ----------
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validate required fields from Description tab (mandatory tab)
    if (!formData.description || formData.description.trim() === "") {
      setSnackbar({
        open: true,
        message:
          "Description is required. Please fill out the Description tab.",
        severity: "error",
      });
      return;
    }

    // Show spinner immediately so the user knows the form is being processed,
    // even while the generateSubject API call is still in-flight (#1548 follow-up).
    setIsSubmitting(true);

    // Capture the resolved subject in a local variable so it is available
    // synchronously for submissionData regardless of whether React has
    // flushed the setFormData state update yet.
    let resolvedSubject = formData.subject;

    if (
      !isEdit &&
      !hasUserEditedSubjectRef.current &&
      formData.description.trim().length >= 10
    ) {
      try {
        const response = await generateSubject(formData.description);
        const generatedSubject = response?.body?.subject;
        if (generatedSubject) {
          resolvedSubject = generatedSubject;
          setFormData((prev) => ({ ...prev, subject: generatedSubject }));
        }
      } catch (error) {
        console.error("Error generating subject:", error);
      }
    }

    // Fallback: if the API failed or returned nothing and the user left the
    // subject blank, derive a subject from the description so it is never null.
    if (!resolvedSubject || resolvedSubject.trim() === "") {
      resolvedSubject = formData.description.trim().slice(0, 70);
      setFormData((prev) => ({ ...prev, subject: resolvedSubject }));
    }

    // NOTE (SAAYAM-1622): otherPersonLocation / otherPersonLocationCoordinates
    // are intentionally NOT added here. There is no API/DB field mapped for
    // the "Other" requester's location yet. Once the backend adds support
    // (geography column), add them to submissionData below, e.g.:
    //   other_person_location: otherPersonLocation,
    //   other_person_location_coordinates: otherPersonLocationCoordinates,
    const submissionData = {
      ...formData,
      subject: resolvedSubject,
      location,
    };
    try {
      // In edit mode, skip the predict-categories modal since category is locked
      if (
        !isEdit &&
        (formData.category === "General" ||
          resolveCatNameToId(formData.category) ===
            resolveCatNameToId("GENERAL_CATEGORY")) &&
        formData.description.trim() !== "" &&
        !categoryConfirmed
      ) {
        await fetchPredictedCategories();
        setShowModal(true);
        return; // Don’t submit yet
      }

      // If there are attached files (selected but not yet uploaded), upload them first
      // IMPORTANT: This uploads each file individually so we can show per-file progress bars
      let uploadedFileUrls = [];

      // If user selected new files (attachedFiles) -> upload them
      if (attachedFiles.length > 0) {
        const urls = await uploadAllAttachedFiles();
        uploadedFileUrls = uploadedFileUrls.concat(urls);
      }

      // Also include previously uploaded files (uploadedFilesInfo)
      if (uploadedFilesInfo.length > 0) {
        const prevUrls = uploadedFilesInfo
          .map((f) => f.fileUrl)
          .filter(Boolean);
        uploadedFileUrls = [...uploadedFileUrls, ...prevUrls];
      }

      // include attachments in submission payload (if any)
      if (uploadedFileUrls.length > 0) {
        submissionData.attachments = uploadedFileUrls;
      }

      // Build the API payload
      const payload = mapHelpRequestPayload({
        formData: submissionData,
        selectedCategoryId: selectedCategoryId ?? formData.category,
        requesterId: isEdit
          ? editRequestData?.requesterId || userDbId
          : userDbId,
        enumMaps,
        additionalFields: additionalFieldValues,
        requestId: isEdit
          ? editRequestData?.requestId || editRequestData?.id || id
          : undefined,
      });

      // Call updateRequest when editing, createRequest when creating
      let response;
      if (isEdit) {
        response = await updateRequest(payload);
      } else {
        response = await createRequest(payload);
      }
      const responseRequestId = response?.data?.requestId;

      setSnackbar({
        open: true,
        message: isEdit
          ? "Help Request updated successfully!"
          : "Help Request submitted successfully!",
        severity: "success",
      });

      setTimeout(() => {
        if (isEdit && onClose) {
          onClose(response?.data);
        } else {
          navigate("/dashboard", {
            state: {
              successMessage: responseRequestId
                ? isEdit
                  ? `Request #${responseRequestId} updated successfully!`
                  : `New Request #${responseRequestId} submitted successfully!`
                : isEdit
                  ? "Help Request updated successfully!"
                  : "Help Request submitted successfully!",
            },
          });
        }
      }, 1200);
    } catch (error) {
      console.error("Failed to process request:", error);
      setSnackbar({
        open: true,
        message: isEdit
          ? "Failed to update request!"
          : "Failed to submit request!",
        severity: "error",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // ---------- RENDER ----------
  if (isLoading) return <div>Loading...</div>;
