                      onChange={(e) => {
                        const selected = e.target.value;
                        const isOther = selected !== enums?.requestFor?.[0]; // not SELF = OTHER
                        const savedPrefs = JSON.parse(
                          localStorage.getItem("userPreferences") || "{}",
                        );
                        const profileLang =
                          savedPrefs.languagePreference1 ||
                          user?.["custom:pref_first_language"] ||
                          user?.first_language_preference ||
                          "";
                        setFormData({
                          ...formData,
                          request_for: selected,
                          preferred_language:
                            isOther && profileLang
                              ? profileLang
                              : formData.preferred_language,
                        });
                        setSelfFlag(!isOther); // "SELF" means true, "OTHER" means false
                      }}
                    >
                      {enums?.requestFor &&
                        Object.values(enums.requestFor).map((val) => (
                          <option key={val} value={val}>
                            {t(`enums:requestFor.${val}`, val)}
                          </option>
                        ))}
                    </select>
                    <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-2">
                      <HiChevronDown className="h-5 w-5 text-gray-600" />
                    </div>
                  </div>
                </div>

                {/* Lead Volunteer */}
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
