import { useState, useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

const METRICS_S3_URL = import.meta.env.VITE_METRICS_CDN_URL || "";
const METRIC_CONFIGS = [
  {
    key: "total_requests",
    labelKey: "TOTAL_REQUESTS",
    suffix: "",
    color: "#1e40af",
    bg: "#dbeafe",
  },
  {
    key: "requests_resolved",
    labelKey: "REQUESTS_RESOLVED",
    suffix: "",
    color: "#166534",
    bg: "#dcfce7",
  },
  {
    key: "total_volunteers",
    labelKey: "TOTAL_VOLUNTEERS",
    suffix: "",
    color: "#5b21b6",
    bg: "#ede9fe",
  },
  {
    key: "total_beneficiaries",
    labelKey: "TOTAL_BENEFICIARIES",
    suffix: "",
    color: "#9a3412",
    bg: "#ffedd5",
  },
];

function useCountUp(target, duration = 1200) {
  const [value, setValue] = useState(0);
  const rafRef = useRef(null);

  useEffect(() => {
    if (target === 0) {
      setValue(0);
      return;
    }
    const start = performance.now();
    const animate = (now) => {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.round(eased * target));
      if (progress < 1) rafRef.current = requestAnimationFrame(animate);
    };
    rafRef.current = requestAnimationFrame(animate);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [target, duration]);

  return value;
}

function MetricItem({ config, rawValue, label }) {
  const animated = useCountUp(rawValue);

  return (
    <span
      className="inline-flex w-full min-w-0 items-center justify-center gap-1.5 px-3 py-1.5 rounded-full text-center sm:w-auto sm:whitespace-nowrap"
      style={{ backgroundColor: config.bg }}
    >
      <span className="text-sm font-medium" style={{ color: config.color }}>
        {label}:
      </span>
      <span
        className="text-sm font-bold tabular-nums"
        style={{ color: config.color }}
      >
        {animated.toLocaleString()}
        {config.suffix}
      </span>
    </span>
  );
}

const MetricsTicker = () => {
  const { t } = useTranslation();
  const [metrics, setMetrics] = useState({
    totalRequests: 0,
    requestsResolved: 0,
    totalVolunteers: 0,
    totalBeneficiaries: 0,
  });

  {
    /* useEffect(() => {
    if (!METRICS_S3_URL) return;
    fetch(METRICS_S3_URL)
      .then((res) => {
        if (!res.ok) throw new Error();
        return res.json();
      })
      .then((data) => setMetrics((prev) => ({ ...prev, ...data })))
      .catch(() => {});
  }, []); */
  }

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const response = await fetch(METRICS_S3_URL);
        const data = await response.json();
        setMetrics(data);
      } catch (err) {
        console.error("Failed to fetch stats:", err);
      }
    };

    fetchStats();
    const interval = setInterval(fetchStats, 4 * 60 * 60 * 1000); // Poll every 4 hours
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="w-full py-3">
      <div className="mx-auto grid w-full max-w-screen-sm grid-cols-2 gap-2 px-4 sm:flex sm:max-w-none sm:flex-wrap sm:items-center sm:justify-center">
        {METRIC_CONFIGS.map((config, index) => (
          <span
            key={config.key}
            className="flex w-full min-w-0 items-center sm:w-auto"
          >
            <MetricItem
              config={config}
              rawValue={metrics[config.key]}
              label={t(config.labelKey)}
            />
            {index < METRIC_CONFIGS.length - 1 && (
              <span className="mx-4 text-gray-300 select-none font-light hidden sm:inline">
                |
              </span>
            )}
          </span>
        ))}
      </div>
    </div>
  );
};

export default MetricsTicker;

import "@testing-library/jest-dom";
import { render, screen, waitFor, act } from "@testing-library/react";
import MetricsTicker from "./MetricsTicker";

jest.mock("react-i18next", () => ({
  useTranslation: () => ({
    t: (key) => key,
  }),
}));

const mockFetchResponse = (data) =>
  Promise.resolve({
    ok: true,
    json: () => Promise.resolve(data),
  });

const mockStats = {
  total_requests: 100,
  requests_resolved: 80,
  total_volunteers: 50,
  total_beneficiaries: 200,
};

beforeEach(() => {
  global.fetch = jest.fn(() => mockFetchResponse(mockStats));
  jest.useFakeTimers();

  // Stub RAF so useCountUp's animation loop doesn't run infinitely in jsdom
  jest.spyOn(window, "requestAnimationFrame").mockImplementation(() => 0);
  jest.spyOn(window, "cancelAnimationFrame").mockImplementation(() => {});
});

afterEach(() => {
  jest.runOnlyPendingTimers();
  jest.useRealTimers();
  jest.restoreAllMocks();
});

describe("MetricsTicker", () => {
  it("renders the four metric labels", () => {
    render(<MetricsTicker />);

    expect(screen.getByText(/TOTAL_REQUESTS/i)).toBeInTheDocument();
    expect(screen.getByText(/REQUESTS_RESOLVED/i)).toBeInTheDocument();
    expect(screen.getByText(/TOTAL_VOLUNTEERS/i)).toBeInTheDocument();
    expect(screen.getByText(/TOTAL_BENEFICIARIES/i)).toBeInTheDocument();
  });

  it("fetches stats on mount", async () => {
    render(<MetricsTicker />);

    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalledTimes(1);
    });
  });

  it("re-fetches stats every 4 hours", async () => {
    render(<MetricsTicker />);

    await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

    act(() => {
      jest.advanceTimersByTime(4 * 60 * 60 * 1000);
    });

    await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(2));
  });

  it("clears the polling interval on unmount", async () => {
    const clearIntervalSpy = jest.spyOn(global, "clearInterval");

    const { unmount } = render(<MetricsTicker />);
    await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

    unmount();

    expect(clearIntervalSpy).toHaveBeenCalled();
  });

  it("handles fetch errors without crashing", async () => {
    global.fetch = jest.fn(() => Promise.reject(new Error("Network error")));
    const consoleSpy = jest
      .spyOn(console, "error")
      .mockImplementation(() => {});

    render(<MetricsTicker />);

    await waitFor(() => {
      expect(consoleSpy).toHaveBeenCalledWith(
        "Failed to fetch stats:",
        expect.any(Error),
      );
    });

    consoleSpy.mockRestore();
  });
});

