    );

    render(
      <OrganizationDetails setHasUnsavedChanges={mockSetHasUnsavedChanges} />,
    );

    fireEvent.click(screen.getByText("Edit"));

    await waitFor(() => {
      expect(screen.getByText("Save")).toBeInTheDocument();
    });
