                    country: getCountryCodeFromZoneInfo(user?.zoneinfo) || "US",
                    state: "",
                    zipCode: "",
                    secondaryEmail: "",
                    secondaryPhone: "",
                    secondaryPhoneCountryCode: "US",
                  });
                }
                setIsEditing(false);
                setErrors({});
                setHasUnsavedChanges(false);
              }}
            >
              {t("CANCEL")}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

