import React, { useEffect, useState, useMemo } from "react";
import { useTranslation } from "react-i18next";
import Comments from "./Comments";
import SearchCancelIconButton from "../../common/components/SearchCancelIconButton/SearchCancelIconButton";

/* // Get the current system date
  const systemDate = new Date();
  const formattedDate = systemDate.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "numeric",
    hour12: true,
  });
  */

const CommentsSection = ({ comments = [] }) => {
  const { t } = useTranslation();
  const [comment, setComment] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(5); // Remove itemsPerPage, use only rowsPerPage
  const [searchText, setSearchText] = useState("");
  const [sortOrder, setSortOrder] = useState("newest");

  // Move filteredComments definition before useEffect
  const filteredComments = useMemo(() => {
    return (comments || [])
      .filter(
        (c) =>
          c.name.toLowerCase().includes(searchText.toLowerCase()) ||
          c.message.toLowerCase().includes(searchText.toLowerCase()),
      )
      .sort((a, b) => {
        const dateA = new Date(a.date);
        const dateB = new Date(b.date);
        return sortOrder === "newest" ? dateB - dateA : dateA - dateB;
      });
  }, [comments, searchText, sortOrder]);

  const totalPages = useMemo(
    () => Math.ceil(filteredComments.length / rowsPerPage) || 1,
    [filteredComments, rowsPerPage],
  );

  const handleCommentChange = (e) => {
    setComment(e.target.value);
  };

  const handleSearchChange = (e) => {
    setSearchText(e.target.value);
    setCurrentPage(1); // Reset to the first page
  };

  const handleSortChange = () =>
    setSortOrder((prev) => (prev === "newest" ? "oldest" : "newest"));

  // Update pagination calculations to use rowsPerPage
  const indexOfLastItem = currentPage * rowsPerPage;
  const indexOfFirstItem = indexOfLastItem - rowsPerPage;
  const currentComments = filteredComments.slice(
    indexOfFirstItem,
    indexOfLastItem,
  );

  const handlePaginationClick = (direction) => {
    if (direction === "next" && currentPage < totalPages) {
      setCurrentPage((prev) => prev + 1);
    } else if (direction === "prev" && currentPage > 1) {
      setCurrentPage((prev) => prev - 1);
    }
  };

  const handlePageChange = (pageNumber) => setCurrentPage(pageNumber);

  const handleRowsPerPageChange = (newRowsPerPage) => {
    setRowsPerPage(newRowsPerPage);
    setCurrentPage(1); // Reset to first page when changing rows per page
  };

  // Update the renderPagination function
  const renderPagination = () => {
    const pageNumbers = [];
    for (let i = 1; i <= totalPages; i++) {
      pageNumbers.push(i);
    }

    return (
      <div className="flex justify-end items-center space-x-2 w-full">
        <button
          onClick={() => handlePageChange(currentPage - 1)}
          disabled={currentPage === 1}
          className={`px-3 py-1 rounded ${
            currentPage === 1
              ? "invisible"
              : "bg-gray-200 hover:bg-gray-300 text-black"
          }`}
        >
          Previous
        </button>

        {pageNumbers.map((number) => (
          <button
            key={number}
            onClick={() => handlePageChange(number)}
            className={`px-3 py-1 rounded ${
              number === currentPage
                ? "bg-blue-500 hover:bg-blue-600 text-white"
                : "bg-gray-200 hover:bg-gray-300 text-black"
            }`}
          >
            {number}
          </button>
        ))}

        <button
          onClick={() => handlePageChange(currentPage + 1)}
          disabled={currentPage === totalPages}
          className={`px-3 py-1 rounded ${
            currentPage === totalPages
              ? "invisible"
              : "bg-gray-200 hover:bg-gray-300 text-black"
          }`}
        >
          Next
        </button>
      </div>
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (comment.trim()) {
      // submit comment logic
      setComment("");
    }
  };

  // TODO: wire to API when available
  const handleEditComment = (_id) => {};
  const handleDeleteComment = (_id) => {};

  return (
    <div>
      <div className="flex items-center justify-between bg-white p-3 rounded">
        <div
          className="flex flex-col sm:flex-row items-start gap-2 w-full"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Comment Input Field */}
          <textarea
            value={comment}
            onChange={handleCommentChange}
            placeholder={t("writeComment")}
            rows={4}
            maxLength={200}
            className="w-full flex-1 px-4 py-3 bg-gray-100 outline-none border-2 border-white 
                       text-gray-600 placeholder-gray-400 text-sm rounded 
                       focus:border-black focus:outline-none resize-none"
          />
          <div className="text-xs text-gray-500 mt-1 text-right">
            {comment.length}/200
          </div>

          {/* Send Button */}
          <button
            className="ml-2 p-2 bg-blue-500 text-white rounded-full hover:bg-blue-600 transition-all"
            onClick={handleSubmit}
          >
            {/* Send message icon - Paper Plane */}
            <svg
              className="w-5 h-5 transform rotate-0"
              fill="currentColor"
              viewBox="0 0 24 24"
              stroke="none"
              style={{ transform: "rotate(-30deg)" }}
            >
              <path d="M2.003 21L23 12 2.003 3 2 10l15 2-15 2 .003 7z" />
            </svg>
          </button>
        </div>
      </div>
      <div onClick={(e) => e.stopPropagation()}>
        <div className="mt-4 bg-gray-100 p-6 shadow-md w-full rounded-lg">
          {/* Search and sort bar - always visible */}
          <div className="bg-gray-100 p-4 rounded-lg">
            <div className="flex flex-col sm:flex-row gap-3 w-full">
              <div className="relative w-full sm:flex-1">
                <input
                  type="text"
                  value={searchText}
                  onChange={handleSearchChange}
                  placeholder="Search..."
                  className="w-full sm:flex-1 pl-4 pr-8 py-2 bg-white shadow-sm rounded border outline-none"
                />
                {searchText && (
                  <SearchCancelIconButton
                    onClick={() => setSearchText("")}
                    className="absolute right-2 top-1/2 -translate-y-1/2"
                  />
                )}
              </div>

              <button
                onClick={handleSortChange}
                className="px-4 py-2 bg-white shadow-sm rounded border shrink-0"
              >
                {t("SORT_BY")}:{" "}
                {sortOrder === "newest" ? t("NEWEST") : t("OLDEST")}
              </button>
            </div>
          </div>

          {/* Comments list or empty state */}
          {filteredComments.length > 0 ? (
            <>
              {currentComments.map((comment) => {
                const { message, name, date, id } = comment;
                return (
                  <Comments
                    key={id}
                    message={message}
                    name={name}
                    date={date}
                    onEdit={() => handleEditComment(id)}
                    onDelete={() => handleDeleteComment(id)}
                  />
                );
              })}

              {/* Update the bottom pagination section */}
              <div className="mt-4 grid grid-cols-3 items-center gap-4">
                {/* Showing text - Left */}
                <div className="text-sm text-gray-600 whitespace-nowrap">
                  {t("Showing")} {indexOfFirstItem + 1} {t("to")}{" "}
                  {Math.min(indexOfLastItem, filteredComments.length)} {t("of")}{" "}
                  {filteredComments.length} {t("comments")}
                </div>

                {/* Rows per page - Center */}
                <div className="flex items-center justify-center gap-2">
                  <span className="text-sm text-gray-600">
                    {t("Rows per view")}:
                  </span>
                  <select
                    value={rowsPerPage}
                    onChange={(e) =>
                      handleRowsPerPageChange(Number(e.target.value))
                    }
                    className="px-3 py-1 border rounded-md text-sm bg-white"
                  >
                    <option value={5}>5</option>
                    <option value={10}>10</option>
                    <option value={20}>20</option>
                  </select>
                </div>

                {/* Pagination - Right */}
                <div className="flex justify-end">{renderPagination()}</div>
              </div>
            </>
          ) : (
            <div className="text-center text-gray-500 py-8">
              {t("NO_COMMENTS_FOUND")}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CommentsSection;

