    {
      id: 3,
      name: "Bob Wilson",
      message: "Third comment here",
      date: "2024-01-16T11:00:00Z",
    },
  ];

  it("renders without crashing", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);
    expect(screen.getByPlaceholderText(/search/i)).toBeInTheDocument();
  });

  it("displays NO_COMMENTS_FOUND when comments array is empty", () => {
    renderWithI18n(<CommentsSection comments={[]} />);
    expect(screen.getByText("No comments found")).toBeInTheDocument();
  });

  it("displays NO_COMMENTS_FOUND when search returns no results", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    fireEvent.change(searchInput, { target: { value: "nonexistent" } });

    expect(screen.getByText("No comments found")).toBeInTheDocument();
  });

  it("filters comments based on search text (name)", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    fireEvent.change(searchInput, { target: { value: "John" } });

    expect(screen.getByText("Test comment message")).toBeInTheDocument();
    expect(screen.queryByText("Another test comment")).not.toBeInTheDocument();
  });

  it("filters comments based on search text (message content)", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    fireEvent.change(searchInput, { target: { value: "Third" } });

    expect(screen.getByText("Third comment here")).toBeInTheDocument();
    expect(screen.queryByText("Test comment message")).not.toBeInTheDocument();
  });

  it("clears search when cancel button is clicked", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    fireEvent.change(searchInput, { target: { value: "test" } });

    const cancelButton = screen.getByLabelText(/clear/i);
    fireEvent.click(cancelButton);

    expect(searchInput.value).toBe("");
  });

  it("sorts comments by newest by default", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);
    const sortButton = screen.getByText(/Sort by/i);
    expect(sortButton).toBeInTheDocument();
  });

  it("toggles sort order when sort button is clicked", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const sortButton = screen.getByText(/Sort by/i);
    fireEvent.click(sortButton);

    expect(screen.getByText(/Oldest/i)).toBeInTheDocument();
  });

  it("resets to page 1 when search text changes", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    fireEvent.change(searchInput, { target: { value: "John" } });

    expect(screen.getByText(/Showing.*1.*to.*1/i)).toBeInTheDocument();
  });

  it("displays pagination when there are multiple pages", () => {
    const manyComments = Array.from({ length: 10 }, (_, i) => ({
      id: i,
      name: `User ${i}`,
      message: `Message ${i}`,
      date: "2024-01-15T10:00:00Z",
    }));

    renderWithI18n(<CommentsSection comments={manyComments} />);

    expect(screen.getByRole("button", { name: "1" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "2" })).toBeInTheDocument();
  });

  it("handles comment submission", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const textarea = screen.getByPlaceholderText(/Write a comment/i);
    fireEvent.change(textarea, { target: { value: "New comment" } });

    // The send button is the blue circular button next to textarea
    const submitButton = screen
      .getAllByRole("button")
      .find((btn) => btn.className?.includes("bg-blue-500"));
    expect(submitButton).toBeTruthy();
    fireEvent.click(submitButton);

    expect(textarea.value).toBe("");
  });

  it("shows character count for comment input", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const textarea = screen.getByPlaceholderText(/Write a comment/i);
    fireEvent.change(textarea, { target: { value: "Hello" } });

    expect(screen.getByText("5/200")).toBeInTheDocument();
  });

  it("handles rows per page change", () => {
    const manyComments = Array.from({ length: 15 }, (_, i) => ({
      id: i,
      name: `User ${i}`,
      message: `Message ${i}`,
      date: "2024-01-15T10:00:00Z",
    }));

    renderWithI18n(<CommentsSection comments={manyComments} />);

    // Find the select element by its text content instead of label
    const select = screen.getByText(/Rows per view/i).nextElementSibling;
    fireEvent.change(select, { target: { value: "10" } });

    expect(screen.getByText(/Showing.*1.*to.*10/i)).toBeInTheDocument();
  });

  it("renders edit button for each visible comment", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const editButtons = screen.getAllByRole("button", {
      name: /edit comment/i,
    });
    expect(editButtons).toHaveLength(mockComments.length);
  });

  it("renders delete button for each visible comment", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const deleteButtons = screen.getAllByRole("button", {
      name: /delete comment/i,
    });
    expect(deleteButtons).toHaveLength(mockComments.length);
  });

  it("clicking edit button does not throw", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const editButtons = screen.getAllByRole("button", {
      name: /edit comment/i,
    });
    expect(() => fireEvent.click(editButtons[0])).not.toThrow();
  });

  it("clicking delete button does not throw", () => {
    renderWithI18n(<CommentsSection comments={mockComments} />);

    const deleteButtons = screen.getAllByRole("button", {
      name: /delete comment/i,
    });
    expect(() => fireEvent.click(deleteButtons[0])).not.toThrow();
  });

  it("edit and delete buttons only show for paginated comments, not all", () => {
    const manyComments = Array.from({ length: 10 }, (_, i) => ({
      id: i,
      name: `User ${i}`,
      message: `Message ${i}`,
      date: "2024-01-15T10:00:00Z",
    }));

    renderWithI18n(<CommentsSection comments={manyComments} />);

    // default rowsPerPage is 5, so only 5 edit/delete buttons should appear
    const editButtons = screen.getAllByRole("button", {
      name: /edit comment/i,
    });
    expect(editButtons).toHaveLength(5);
  });
});

src/pages/RequestDetails/HelpingVoluntee:
import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { getVolunteersData } from "../../services/volunteerServices";
import {
  createZoomMeeting,
  storeMeetingDetails,
} from "../../services/meetingServices";
import { FaVideo } from "react-icons/fa";
import { Link } from "react-router-dom";

const HelpingVolunteers = () => {
  const { t } = useTranslation();
  // Modal state for Zoom meeting scheduling
  const [meetingModalOpen, setMeetingModalOpen] = useState(false);
  const [meetingDate, setMeetingDate] = useState("");
  const [meetingTime, setMeetingTime] = useState("");
  const [meetingLoading, setMeetingLoading] = useState(false);
  const [selectAll, setSelectAll] = useState(false);
  const [meetingError, setMeetingError] = useState("");
  const [meetingSuccess, setMeetingSuccess] = useState("");

  // Auto-hide meeting success message after 2 seconds
  useEffect(() => {
    if (meetingSuccess) {
      const timer = setTimeout(() => setMeetingSuccess(""), 2000);
      return () => clearTimeout(timer);
    }
  }, [meetingSuccess]);
  const [isOpen, setIsOpen] = useState(false);
  const [chooseVolunteer, setChooseVolunteer] = useState(true);
  const [volunteersCount, setVolunteersCount] = useState(2);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(5);
  const [sortConfig, setSortConfig] = useState({
    key: "name",
    direction: "ascending",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [searchBy, setSearchBy] = useState("name");
  const [filter, setFilter] = useState(""); // State for filter functionality
  const [sortBy, setSortBy] = useState("Newest"); // State for sort functionality
  const [volunteerCountError, setVolunteerCountError] = useState("");

  // Get the current system date
  const systemDate = new Date();
  const formattedDate = systemDate.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "numeric",
    hour12: true,
  });

  // api integrated code

  const [volunteerData, setVolunteerData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchVolunteers = async () => {
      try {
        setLoading(true);
        const list = await getVolunteersData();
        setVolunteerData(Array.isArray(list) ? list : []);
      } catch (err) {
        setError(err?.message || "Failed to fetch volunteers");
      } finally {
        setLoading(false);
      }
    };
    fetchVolunteers();
  }, []);

  // Columns for the table
  const headers = [
    { key: "select", label: "Select" },
    { key: "name", label: "Name" },
    { key: "cause", label: "Cause" },
    { key: "phone", label: "Phone" },
    { key: "email", label: "Email" },
    { key: "location", label: "Location" },
    { key: "rating", label: "Rating" },
  ];

  // State for selected volunteers
  const [selectedVolunteers, setSelectedVolunteers] = useState([]);

  // Handle checkbox change
  const handleCheckboxChange = (email) => {
    setSelectedVolunteers((prev) =>
      prev.includes(email) ? prev.filter((e) => e !== email) : [...prev, email],
    );
  };
  const handleSelectAll = (checked) => {
    if (checked) {
      const emails = paginatedData.map((v) => v.email);
      setSelectedVolunteers(emails);
    } else {
      setSelectedVolunteers([]);
    }
  };

  // Sorting function based on dropdown selection and column clicks
  const requestSort = (key) => {
    let direction = "ascending";
    if (sortConfig.key === key && sortConfig.direction === "ascending") {
      direction = "descending";
    }
    setSortConfig({ key, direction });
  };

  // Sorting and filtering logic
  const filteredAndSortedVolunteers = useMemo(() => {
    let topN = volunteerData.slice(
      0,
      Math.min(volunteerData.length, volunteersCount),
    );
    let filteredVolunteers = topN.filter((volunteer) => {
      return (volunteer.name || "")
        .toLowerCase()
        .includes(searchTerm.toLowerCase());
    });

    if (filter) {
      filteredVolunteers = filteredVolunteers.filter((volunteer) =>
        volunteer.cause.toLowerCase().includes(filter.toLowerCase()),
      );
    }

    filteredVolunteers.sort((a, b) => {
      if (sortConfig.key === "dateAdded") {
        const dateA = new Date(a.dateAdded);
        const dateB = new Date(b.dateAdded);
        return sortConfig.direction === "ascending"
          ? dateA - dateB
          : dateB - dateA;
      } else {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === "ascending" ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === "ascending" ? 1 : -1;
        }
        return 0;
      }
    });

    return filteredVolunteers;
  }, [volunteerData, searchTerm, filter, sortConfig, volunteersCount]);

  const totalRows = filteredAndSortedVolunteers.length;
  const totalPages = Math.ceil(totalRows / itemsPerPage);

  // Pagination Logic
  const paginatedData = filteredAndSortedVolunteers.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );
  useEffect(() => {
    if (paginatedData.length > 0) {
      const allSelected = paginatedData.every((v) =>
        selectedVolunteers.includes(v.email),
      );
      setSelectAll(allSelected);
    }
  }, [selectedVolunteers, paginatedData]);

  const volunteersAssigned = filteredAndSortedVolunteers.length;

  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(Number(e.target.value));
    setCurrentPage(1); // Reset to page 1 when items per page changes
  };

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  const paginationButtons = [];
  for (let i = 1; i <= totalPages; i++) {
    paginationButtons.push(
      <button
        key={i}
        className={`px-3 py-1 rounded ${
          i === currentPage
            ? "bg-blue-500 hover:bg-blue-600 text-white"
            : "bg-gray-200 hover:bg-gray-300 text-black"
        }`}
        onClick={() => handlePageChange(i)}
      >
        {i}
      </button>,
    );
  }

  return (
    <div className="w-full border border-gray-300 rounded-md">
      {loading && (
        <div className="text-center py-8 text-lg font-semibold" role="status">
          Loading...
        </div>
      )}
      {error && (
        <div className="text-red-600 font-semibold px-4 pt-4" role="alert">
          {error}
        </div>
      )}
      <div className="flex justify-between items-center px-4 pt-4">
        <div className="flex items-center gap-4">
          <div className="font-bold text-lg">Volunteer Management</div>
          {volunteerCountError && (
            <div className="text-red-600 text-sm font-semibold flex items-center gap-1">
              <span aria-hidden="true">⚠️</span>
              <span>{volunteerCountError}</span>
            </div>
          )}
        </div>
        {meetingModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 transition-opacity duration-300">
            <div className="bg-white rounded-2xl shadow-2xl p-8 w-full max-w-md animate-fadeIn relative">
              <button
                className="absolute top-3 right-3 text-gray-400 hover:text-gray-700 text-2xl font-bold focus:outline-none"
                onClick={() => {
                  setMeetingModalOpen(false);
                  setMeetingDate("");
                  setMeetingTime("");
                  setMeetingError("");
                }}
                disabled={meetingLoading}
                aria-label="Close"
              >
                &times;
              </button>
              <div className="flex items-center gap-3 mb-6">
                <FaVideo className="text-2xl text-blue-500" />
                <h2 className="text-2xl font-bold tracking-tight">
                  Schedule Zoom Meeting
                </h2>
              </div>
              <div className="mb-5">
                <label
                  htmlFor="meeting-date"
                  className="block mb-1 font-semibold text-gray-700"
                >
                  Date
                </label>
                <input
                  id="meeting-date"
                  type="date"
                  className="border-2 border-gray-200 rounded-lg px-4 py-2 w-full focus:border-blue-400 focus:outline-none transition"
                  value={meetingDate}
                  min={new Date().toISOString().split("T")[0]}
                  onChange={(e) => setMeetingDate(e.target.value)}
                  disabled={meetingLoading}
                />
              </div>
              <div className="mb-5">
                <label
                  htmlFor="meeting-time"
                  className="block mb-1 font-semibold text-gray-700"
                >
                  Time
                </label>
                <input
                  id="meeting-time"
                  type="time"
                  className="border-2 border-gray-200 rounded-lg px-4 py-2 w-full focus:border-blue-400 focus:outline-none transition"
                  value={meetingTime}
                  onChange={(e) => setMeetingTime(e.target.value)}
                  disabled={meetingLoading}
                />
              </div>
              {meetingSuccess && (
                <div className="text-yellow-600 bg-yellow-50 border border-yellow-300 rounded-lg px-4 py-3 mb-3 font-medium text-sm">
                  ⚠️ {meetingSuccess}
                </div>
              )}
              {meetingError && (
                <div className="text-red-600 mb-3 font-medium animate-shake">
                  {meetingError}
                </div>
              )}
              <div className="flex justify-end gap-3 mt-8">
                <button
                  className="px-5 py-2 rounded-lg bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold transition"
                  onClick={() => {
                    setMeetingModalOpen(false);
                    setMeetingDate("");
                    setMeetingTime("");
                    setMeetingError("");
                  }}
                  disabled={meetingLoading}
                >
                  Cancel
                </button>
                <button
                  className="px-6 py-2 rounded-lg bg-gradient-to-r from-blue-600 to-purple-600 text-white font-bold shadow hover:from-blue-700 hover:to-purple-700 transition disabled:opacity-50"
                  onClick={async () => {
                    if (!meetingDate || !meetingTime) {
                      setMeetingError("Please select both date and time.");
                      return;
                    }
                    setMeetingError("");
                    // TODO: Need to integrate with backend
                    setMeetingSuccess("TODO: Need to integrate with backend");
                  }}
                  disabled={meetingLoading}
                >
                  {meetingLoading ? (
                    <span className="flex items-center gap-2">
                      <svg
                        className="animate-spin h-5 w-5 text-white"
                        xmlns="http://www.w3.org/2000/svg"
                        fill="none"
                        viewBox="0 0 24 24"
                      >
                        <circle
                          className="opacity-25"
                          cx="12"
                          cy="12"
                          r="10"
                          stroke="currentColor"
                          strokeWidth="4"
                        ></circle>
                        <path
                          className="opacity-75"
                          fill="currentColor"
                          d="M4 12a8 8 0 018-8v8z"
                        ></path>
                      </svg>{" "}
                      Scheduling...
                    </span>
                  ) : (
                    "Confirm"
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
      <div className="bg-gray-100 shadow-md p-1 space-y-4 rounded-b-md">
        <div className="flex flex-wrap items-stretch gap-4 p-4 mt-2">
          {/* Box 1: Request by number of volunteers */}
          <div className="flex items-center gap-4 bg-white border border-gray-300 rounded-xl p-4">
            <input
              type="number"
              min="1"
              max="5"
              placeholder={t("NUMBER_OF_VOLUNTEERS")}
              className="p-3 border rounded-md w-40"
              value={volunteersCount}
              onChange={(e) => {
                setVolunteersCount(e.target.value);
                setChooseVolunteer(false);
                if (Number(e.target.value) <= 5) {
                  setVolunteerCountError("");
                }
              }}
            />
            <button
              className="bg-blue-500 px-6 py-3 text-white rounded-lg whitespace-nowrap hover:bg-blue-600 flex items-center"
              onClick={() => {
                const requestedCount = Number(volunteersCount);
                if (requestedCount > 5) {
                  setVolunteerCountError("Maximum 5 volunteer can be assigned");
                  return;
                }
                setVolunteerCountError("");
                setChooseVolunteer(true);
              }}
            >
              <svg
                className="w-5 h-5 mr-2"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M12 4v16m8-8H4"
                />
              </svg>
              {t("REQUEST_VOLUNTEERS")}
            </button>
          </div>

          {/* Separator line between the two search boxes */}
          <div className="w-px self-stretch bg-gray-300" aria-hidden="true" />

          {/* Box 2: Look up a volunteer by name, email or phone */}
          <div className="flex items-center gap-4 bg-white border border-gray-300 rounded-xl p-4">
            <input
              type="text"
              placeholder={
                searchBy === "email"
                  ? t("ENTER_VOLUNTEER_EMAIL")
                  : searchBy === "phone"
                    ? t("ENTER_VOLUNTEER_PHONE")
                    : t("ENTER_VOLUNTEER_NAME")
              }
              className="p-3 border rounded-md w-64"
            />
            <select
              value={searchBy}
              onChange={(e) => setSearchBy(e.target.value)}
              className="bg-blue-500 px-4 py-3 text-white rounded-lg whitespace-nowrap hover:bg-blue-600 cursor-pointer"
            >
              <option value="name">{t("FIND_BY_NAME")}</option>
              <option value="email">{t("FIND_BY_EMAIL")}</option>
              <option value="phone">{t("FIND_BY_PHONE")}</option>
            </select>
          </div>
        </div>

        <div className="mt-6 bg-white p-6 shadow-lg">
          <div className="flex flex-wrap items-center gap-4 justify-between mb-4">
            <div className="flex flex-row gap-4 items-center">
              {/* Volunteers Title */}
              <div className="font-bold text-xl">Volunteers</div>
              {/* Search Input */}
              <div className="flex-grow max-w-md">
                <input
                  type="text"
                  placeholder={t("SEARCH_BY_NAME")}
                  className="p-2 border border-gray-300 rounded-md w-full"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              {/* Sort By Dropdown */}
              <select
                value={sortBy}
                onChange={(e) => {
                  const value = e.target.value;
                  setSortBy(value);
                  if (value === "Newest") {
                    setSortConfig({
                      key: "dateAdded",
                      direction: "descending",
                    });
                  } else if (value === "Oldest") {
                    setSortConfig({ key: "dateAdded", direction: "ascending" });
                  } else if (value === "Name") {
                    setSortConfig({ key: "name", direction: "ascending" });
                  }
                }}
                className="p-2 border border-gray-300 rounded-md"
              >
                <option value="Newest">Sort by: Newest</option>
                <option value="Oldest">Sort by: Oldest</option>
                <option value="Name">Sort by: Name</option>
              </select>
            </div>

            {/* Right: Zoom + Delete */}
            <div className="flex flex-row gap-2 items-center">
              {/* Zoom Meeting Button */}
              <button
                className="flex items-center gap-2 bg-gradient-to-r from-purple-600 to-blue-500 hover:from-purple-700 hover:to-blue-600 text-white font-semibold px-5 py-2.5 rounded-lg shadow-md transition-all duration-200 disabled:opacity-50"
                disabled={selectedVolunteers.length === 0}
                onClick={() => setMeetingModalOpen(true)}
              >
                <FaVideo className="text-lg" />
                <span>Zoom Meeting</span>
              </button>
              {/* Delete Button */}
              <button
                className="bg-red-500 text-white text-sm px-6 py-2 rounded-lg hover:bg-red-600 disabled:opacity-50"
                disabled={selectedVolunteers.length === 0}
                onClick={() => {
                  setVolunteerData((prev) =>
                    prev.filter(
                      (volunteer) =>
                        !selectedVolunteers.includes(volunteer.email),
                    ),
                  );
                  setSelectedVolunteers([]);
                }}
              >
                {t("Delete")}
              </button>
            </div>
          </div>

          {chooseVolunteer && (
            <div className="flex justify-between w-full mb-4">
              <div className="text-md text-gray-500 font-bold flex flex-row gap-4 items-center">
                {`${volunteersCount} Volunteers Requested`}
                {/* Badge with number */}
                <div className="bg-blue-500 text-white text-sm font-semibold px-2 py-1 rounded-full">
                  {`${volunteersAssigned} Assigned`}
                </div>
              </div>
              <div className="text-md text-gray-600 font-light">{`${formattedDate}`}</div>
            </div>
          )}

          {/* Table inside a scrollable container */}
          <div className="overflow-x-auto">
            <table className="min-w-full bg-white border border-gray-300">
              <thead>
                <tr>
                  {headers.map((header) => (
                    <th
                      key={header.key}
                      onClick={
                        header.key !== "select"
                          ? () => requestSort(header.key)
                          : undefined
                      }
                      className="px-4 py-2 border-b-2 border-gray-200 text-left cursor-pointer"
                    >
                      {header.key === "select" ? (
                        <input
                          type="checkbox"
                          checked={selectAll}
                          onChange={(e) => {
                            setSelectAll(e.target.checked);
                            handleSelectAll(e.target.checked);
                          }}
                        />
                      ) : (
                        <>
                          {header.label}
                          {sortConfig.key === header.key && (
                            <span>
                              {sortConfig.direction === "ascending"
                                ? " 🔼"
                                : " 🔽"}
                            </span>
                          )}
                        </>
                      )}
                    </th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {chooseVolunteer &&
                  paginatedData.map((volunteer, index) => (
                    <tr key={index} className="hover:bg-gray-100">
                      <td className="px-4 py-2 border-b">
                        <input
                          type="checkbox"
                          checked={selectedVolunteers.includes(volunteer.email)}
                          onChange={() => {
                            handleCheckboxChange(volunteer.email);
                          }}
                        />
                      </td>
                      <td className="px-4 py-2 border-b">
                        <Link
                          to={`/profile`}
                          className="text-blue-600 hover:underline"
                        >
                          {volunteer.name}
                        </Link>
                      </td>
                      <td className="px-4 py-2 border-b">{volunteer.cause}</td>
                      <td className="px-4 py-2 border-b">{volunteer.phone}</td>
                      <td className="px-4 py-2 border-b">{volunteer.email}</td>
                      <td className="px-4 py-2 border-b">
                        {volunteer.location}
                      </td>
                      <td className="px-4 py-2 border-b">{volunteer.rating}</td>
                    </tr>
                  ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {chooseVolunteer && (
            <div className="flex justify-between items-center mt-4">
              <div className="text-sm text-gray-600">
                Showing {itemsPerPage * (currentPage - 1) + 1} to{" "}
                {Math.min(itemsPerPage * currentPage, totalRows)} of {totalRows}{" "}
                entries
              </div>
              {/* Items Per Page Selector */}
              <div>
                <label htmlFor="itemsPerPage" className="mr-2">
                  Rows per view:
                </label>
                <select
                  id="itemsPerPage"
                  value={itemsPerPage}
                  onChange={handleItemsPerPageChange}
                  className="p-2 border border-gray-300 rounded-md"
                >
                  <option value={5}>5 rows</option>
                  <option value={10}>10 rows</option>
                  <option value={20}>20 rows</option>
                </select>
              </div>
              <div className="flex items-center space-x-2">
                <button
                  className={`bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600 ${
                    currentPage === 1 ? "invisible" : ""
                  }`}
                  onClick={() =>
                    setCurrentPage((prev) => Math.max(prev - 1, 1))
                  }
                  disabled={currentPage === 1}
                >
                  Previous
                </button>

                {/* Page Numbers */}
                {paginationButtons}

                <button
                  className={`bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600 ${
                    currentPage === totalPages ? "invisible" : ""
                  }`}
                  onClick={() =>
                    setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                  }
                  disabled={currentPage === totalPages}
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

