import React from "react"; //added for testing
import { useTranslation } from "react-i18next";

const Stepper = ({ steps, currentStep }) => {
  const { t } = useTranslation();
  // === WIDTH OF GREEN PROGRESS LINE ===
  const progressWidth =
    currentStep === 1
      ? "0%"
      : `${((currentStep - 1) / (steps.length - 1)) * 100}%`;

  return (
    <div className="relative mx-2 sm:mx-4 p-2 sm:p-4 flex justify-between items-start mb-8 w-full">
      {/* CIRCLES + LABELS */}
      {steps.map((step, index) => {
        const completed = index < currentStep - 1;
        const selected = index <= currentStep - 1;
        const highlighted = index <= currentStep - 1;

        return (
          <div key={index} className="flex flex-col items-center z-10 w-full">
            {/* Circle */}
            <div
              className={`rounded-full border-2 h-12 w-12 flex items-center justify-center transition 
                ${
                  selected
                    ? "bg-green-600 text-white border-green-600 font-bold"
                    : "border-gray-300 text-gray-700"
                }`}
            >
              {completed ? (
                <span className="text-white font-bold text-xl">&#10003;</span>
              ) : (
                t(`STEP_NUMBER_${index + 1}`)
              )}
            </div>

            {/* Label */}
            <div
              className={`mt-2 text-center text-[10px] sm:text-xs font-medium uppercase 
                ${highlighted ? "text-gray-900" : "text-gray-600"}`}
            >
              {step}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default Stepper;

src/pages/Volunteer/StepperControl.jsx:
import PropTypes from "prop-types";
import { useTranslation } from "react-i18next";
import { Tooltip } from "react-tooltip";

const StepperControl = ({
  handleClick,
  currentStep,
  steps,
  isAcknowledged,
  isUploaded,
  isCheckedCategories,
  isAvailabilityValid,
}) => {
  const { t } = useTranslation();

  const disabledCondition =
    (currentStep === 1 && !isAcknowledged) ||
    (currentStep === 2 && !isUploaded) ||
    (currentStep === 3 && !isCheckedCategories) ||
    (currentStep === 4 && !isAvailabilityValid) ||
    currentStep >= steps.length;

  return (
    <div className="container flex justify-around mt-16 mb-8">
      <div className="px-4 w-24">
        <button
          className={`bg-white text-slate-900 uppercase py-2 px-4 rounded-xl font-semibold border-2 border-slate-900 transition duration-200 ease-in-out ${
            currentStep === 1
              ? "opacity-50 cursor-not-allowed"
              : "cursor-pointer hover:bg-slate-700 hover:text-white"
          }`}
          onClick={() => handleClick("prev")}
          disabled={currentStep === 1}
        >
          {t("common:BACK") || "Back"}
        </button>
      </div>
      <div className="px-4 w-24">
        <button
          onClick={() => handleClick("next")}
          className={`uppercase py-2 px-4 rounded-xl font-semibold transition duration-200 ease-in-out border-2 ${
            disabledCondition
              ? "bg-green-300 text-gray border-green-300 opacity-50 cursor-not-allowed"
              : "bg-green-500 text-white border-green-600 cursor-pointer hover:bg-slate-700 hover:text-white"
          }`}
          disabled={disabledCondition}
          data-testid="next-button"
          data-tooltip-id="next-button-tooltip"
          data-tooltip-content={
            currentStep === 3 && !isCheckedCategories
              ? t("common:SELECT_SKILL_TO_CONTINUE")
              : currentStep === 1 && !isAcknowledged
              ? t("TOOLTIP_ACCEPT_TERMS")
              : currentStep === 2 && !isUploaded
              ? t("TOOLTIP_UPLOAD_GOVT_ID")
              : ""
          }
        >
          {currentStep === steps.length - 1
            ? t("common:CONFIRM") || "Confirm"
            : t("common:NEXT") || "Next"}
        </button>
        {(currentStep === 3 && !isCheckedCategories) || 
         (currentStep === 1 && !isAcknowledged) || 
         (currentStep === 2 && !isUploaded) ? (
          <Tooltip
            id="next-button-tooltip"
            place="top"
            style={{ backgroundColor: "#1f2937", color: "#fff" }}
          />
        ) : null}
      </div>
    </div>
  );
};
StepperControl.propTypes = {
  handleClick: PropTypes.func.isRequired,
  currentStep: PropTypes.number.isRequired,
  steps: PropTypes.array.isRequired,
  isAcknowledged: PropTypes.bool.isRequired,
  isUploaded: PropTypes.bool.isRequired,
  isCheckedCategories: PropTypes.bool.isRequired,
  isAvailabilityValid: PropTypes.bool.isRequired,
};

export default StepperControl;

