import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  loading: true,
  user: null,
  success: false,
  error: null,
};

const authSlice = createSlice({
  name: "auth",
  initialState,
  reducers: {
    loginRequest: (state) => {
      state.loading = true;
      state.error = null;
    },
    loginSuccess: (state, action) => {
      state.loading = false;
      state.user = action.payload.user;
    },
    loginFailure: (state, action) => {
      state.loading = false;
      state.error = action.payload;
    },
    logoutSuccess: (state) => {
      state.user = null;
    },
    resetPasswordRequest: (state) => {
      state.loading = true;
      state.success = false;
      state.error = null;
    },
    resetPasswordSuccess: (state) => {
      state.loading = false;
      state.success = true;
      state.error = null;
    },
    resetPasswordFailure: (state, action) => {
      state.loading = false;
      state.success = false;
      state.error = action.payload;
    },

    // New reducer to update user profile in Redux state
    updateUserProfileSuccess: (state, action) => {
      if (state.user) {
        state.user = {
          ...state.user,
          ...action.payload,
          // Ensure we don't overwrite critical fields with undefined
          given_name: action.payload.given_name ?? state.user.given_name,
          family_name: action.payload.family_name ?? state.user.family_name,
          email: action.payload.email ?? state.user.email,
          phone_number: action.payload.phone_number ?? state.user.phone_number,
          zoneinfo: action.payload.zoneinfo ?? state.user.zoneinfo,
        };
      }
    },
  },
});

export const {
  loginRequest,
  loginSuccess,
  loginFailure,
  logoutSuccess,
  resetPasswordRequest,
  resetPasswordSuccess,
  resetPasswordFailure,
  updateUserProfileSuccess,
} = authSlice.actions;

export default authSlice.reducer;

import authReducer, {
  loginRequest,
  loginSuccess,
  loginFailure,
} from "./authSlice";

describe("authSlice", () => {
  describe("initialState", () => {
    it("starts with loading: true so protected routes wait for auth check", () => {
      const state = authReducer(undefined, { type: "@@INIT" });
      expect(state.loading).toBe(true);
    });

    it("starts with user: null", () => {
      const state = authReducer(undefined, { type: "@@INIT" });
      expect(state.user).toBeNull();
    });
  });

  describe("loginRequest", () => {
    it("sets loading: true", () => {
      const state = authReducer({ loading: false, user: null }, loginRequest());
      expect(state.loading).toBe(true);
    });
  });

  describe("loginSuccess", () => {
    it("sets loading: false and stores the user", () => {
      const mockUser = { userId: "u1", email: "test@example.com" };
      const state = authReducer(
        { loading: true, user: null },
        loginSuccess({ user: mockUser }),
      );
      expect(state.loading).toBe(false);
      expect(state.user).toEqual(mockUser);
    });
  });

  describe("loginFailure", () => {
    it("sets loading: false so ProtectedRoute stops showing the loader", () => {
      const state = authReducer(
        { loading: true, user: null },
        loginFailure("Auth error"),
      );
      expect(state.loading).toBe(false);
      expect(state.user).toBeNull();
    });
  });
});

